public sealed class PoliticaAcceso
{
    private readonly DecisionAcceso _decisionPermitida = DecisionAcceso.Permitir();

    public DecisionAcceso EvaluarIdentidad(Usuario usuario, DirectorioAcademico directorio) =>
        ExisteIdentidad(usuario, directorio)
            ? _decisionPermitida
            : DecisionAcceso.Denegar(MotivoDenegacion.IdentidadInvalida);

    public DecisionAcceso EvaluarPregunta(Usuario usuario, string pregunta, DirectorioAcademico directorio)
    {
        var texto = NormalizadorTexto.Normalizar(pregunta);
        var motivo = MotivoTercero(usuario, texto, directorio)
            ?? MotivoPrograma(usuario, texto, directorio)
            ?? MotivoAgregado(usuario, texto)
            ?? MotivoCapacidadAjena(usuario, texto, directorio);
        return motivo is { } denegado ? DecisionAcceso.Denegar(denegado) : DecisionAcceso.Permitir();
    }

    public DecisionAcceso EvaluarLecturaEstudiante(Usuario usuario, string estudianteId, DirectorioAcademico directorio) =>
        PuedeLeerEstudiante(usuario, estudianteId, directorio)
            ? DecisionAcceso.Permitir()
            : DecisionAcceso.Denegar(MotivoDenegacion.HerramientaIdAjeno);

    public IReadOnlyList<string> ProgramasAutorizados(Usuario usuario, DirectorioAcademico directorio) =>
        EvaluarIdentidad(usuario, directorio).Permitido ? AmbitoPersonal.ProgramasDe(usuario, directorio) : [];

    public IReadOnlyList<string> IdsPersonasAutorizadas(Usuario usuario, DirectorioAcademico directorio)
    {
        if (!EvaluarIdentidad(usuario, directorio).Permitido)
        {
            return [];
        }

        var ambito = AmbitoPersonal.De(usuario, directorio);
        return [.. directorio.Estudiantes.Select(e => e.Id)
            .Concat(directorio.Coordinadores.Select(c => c.Id))
            .Where(id => ambito.ClavesDeNombre.Contains(AmbitoPersonal.Clave(id)))];
    }

    private static bool ExisteIdentidad(Usuario usuario, DirectorioAcademico directorio) => usuario.Rol switch
    {
        Rol.Estudiante => Identificadores.EsIdEstudiante(usuario.Id) && directorio.Estudiantes.Any(e => e.Id == usuario.Id),
        Rol.Coordinador => Identificadores.EsIdCoordinador(usuario.Id) && directorio.Coordinadores.Any(c => c.Id == usuario.Id),
        _ => false
    };

    private bool PuedeLeerEstudiante(Usuario usuario, string estudianteId, DirectorioAcademico directorio)
    {
        var estudiante = directorio.Estudiantes.FirstOrDefault(e => e.Id == estudianteId);
        if (estudiante is null || !Identificadores.EsIdEstudiante(estudianteId))
        {
            return false;
        }

        return usuario.Rol == Rol.Estudiante
            ? usuario.Id == estudianteId
            : ProgramasAutorizados(usuario, directorio).Contains(estudiante.ProgramaId);
    }

    private static MotivoDenegacion? MotivoTercero(Usuario usuario, string texto, DirectorioAcademico directorio) =>
        DetectorTerceros.MencionaTercero(usuario, texto, directorio) ? MotivoDenegacion.TerceroMencionado : null;

    private MotivoDenegacion? MotivoPrograma(Usuario usuario, string texto, DirectorioAcademico directorio) =>
        usuario.Rol == Rol.Coordinador && DetectorProgramas.MencionaProgramaAjeno(texto, ProgramasAutorizados(usuario, directorio), directorio)
            ? MotivoDenegacion.ProgramaAjeno
            : null;

    private static MotivoDenegacion? MotivoAgregado(Usuario usuario, string texto) =>
        usuario.Rol == Rol.Estudiante && DetectorAgregados.PideAgregados(texto) ? MotivoDenegacion.Agregado : null;

    private static MotivoDenegacion? MotivoCapacidadAjena(Usuario usuario, string texto, DirectorioAcademico directorio) =>
        DetectorCapacidadAjena.PideCapacidadAjena(usuario, texto, directorio) ? MotivoDenegacion.CapacidadAjena : null;
}
namespace TutorFlow.Core.Autorizacion;

internal sealed class FrasesDelTexto(string textoNormalizado)
{
    private readonly IReadOnlyList<string> _palabras = TokenizadorTexto.Valores(textoNormalizado);

    public bool Contiene(IEnumerable<string> frases) =>
        frases.Any(frase => Posiciones(frase).Any());

    public bool ContieneSeguidaDe(IEnumerable<string> frases, IReadOnlyCollection<string> siguientes) =>
        frases.Any(frase => Posiciones(frase).Any(posicion => EmpiezaAlgunaEn(posicion + Palabras(frase).Length, siguientes)));

    private static string[] Palabras(string frase) => frase.Split(' ');

    private bool EmpiezaAlgunaEn(int indice, IEnumerable<string> frases) =>
        frases.Any(frase => EmpiezaEn(indice, frase));

    private IEnumerable<int> Posiciones(string frase) =>
        Enumerable.Range(0, _palabras.Count).Where(indice => EmpiezaEn(indice, frase));

    private bool EmpiezaEn(int indice, string frase)
    {
        var palabras = Palabras(frase);
        return indice + palabras.Length <= _palabras.Count
            && palabras.Select((palabra, desplazamiento) => _palabras[indice + desplazamiento] == palabra).All(coincide => coincide);
    }
}
using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace TutorFlow.Core.Autorizacion;

internal readonly record struct TokenTexto(string Valor, int Inicio, int Fin);

internal static partial class TokenizadorTexto
{
    private const int UnDigito = 1;
    private const int HastaDosDigitos = 2;
    private const int SinLimite = int.MaxValue;
    private static readonly Dictionary<string, string> NombreDelSimbolo = new() { ["≤"] = "<=", ["≥"] = ">=" };

    public static IReadOnlyList<TokenTexto> Tokenizar(string texto)
    {
        var acumulador = new AcumuladorTokens();
        var inicio = 0;
        foreach (var rune in texto.EnumerateRunes())
        {
            var fin = inicio + rune.Utf16SequenceLength;
            ProcesarRune(acumulador, rune, inicio, fin);
            inicio = fin;
        }

        acumulador.Cerrar();
        return acumulador.Tokens;
    }

    public static IReadOnlyList<TokenTexto> TokenizarConCifras(string texto)
    {
        var tokens = Tokenizar(texto);
        var resultado = new List<TokenTexto>();
        for (var indice = 0; indice < tokens.Count; indice++)
        {
            var esCifra = EsCifraDeNota(texto, tokens, indice);
            resultado.Add(esCifra
                ? new TokenTexto(tokens[indice].Valor + "." + tokens[indice + 1].Valor, tokens[indice].Inicio, tokens[indice + 1].Fin)
                : tokens[indice]);
            indice += esCifra ? 1 : 0;
        }

        return [.. resultado.Concat(Simbolos(texto)).OrderBy(token => token.Inicio)];
    }

    public static int BuscarSecuencia(IReadOnlyList<TokenTexto> tokens, IReadOnlyList<string> secuencia) =>
        BuscarSecuencias(tokens, secuencia).DefaultIfEmpty(-1).First();

    public static IEnumerable<int> BuscarSecuencias(IReadOnlyList<TokenTexto> tokens, IReadOnlyList<string> secuencia) =>
        Enumerable.Range(0, Math.Max(0, tokens.Count - secuencia.Count + 1))
            .Where(indice => CoincideEn(tokens, indice, secuencia));

    public static string Plegado(string texto) =>
        string.Concat(texto.EnumerateRunes().SelectMany(PlegadoCompatibilidad.De).Select(char.ToLowerInvariant));

    public static IReadOnlyList<string> Valores(string texto) =>
        Tokenizar(texto).Select(token => token.Valor).ToList();

    private static IEnumerable<TokenTexto> Simbolos(string texto) =>
        SimboloDeComparacion().Matches(texto)
            .Select(coincidencia => new TokenTexto(NombreDelSimbolo.GetValueOrDefault(coincidencia.Value, coincidencia.Value), coincidencia.Index, coincidencia.Index + coincidencia.Length));

    private static bool EsCifraDeNota(string texto, IReadOnlyList<TokenTexto> tokens, int indice) =>
        indice + 1 < tokens.Count
        && FormaDeCifra(texto, tokens[indice], tokens[indice + 1])
        && !ContinuaUnaCifra(texto, tokens, indice - 1, indice)
        && !ContinuaUnaCifra(texto, tokens, indice + 1, indice + 2);

    private static bool FormaDeCifra(string texto, TokenTexto entera, TokenTexto decimales) =>
        EsDigitos(entera.Valor, UnDigito) && EsDigitos(decimales.Valor, HastaDosDigitos) && UnidosPorPunto(texto, entera, decimales);

    private static bool ContinuaUnaCifra(string texto, IReadOnlyList<TokenTexto> tokens, int desde, int hasta) =>
        desde >= 0
        && hasta < tokens.Count
        && EsDigitos(tokens[desde].Valor, SinLimite)
        && EsDigitos(tokens[hasta].Valor, SinLimite)
        && UnidosPorPunto(texto, tokens[desde], tokens[hasta]);

    private static bool EsDigitos(string valor, int maximo) =>
        valor.Length <= maximo && valor.All(char.IsAsciiDigit);

    private static bool UnidosPorPunto(string texto, TokenTexto anterior, TokenTexto siguiente) =>
        PlegadoCompatibilidad.Aplicar(texto[anterior.Fin..siguiente.Inicio]) == ".";

    private static bool CoincideEn(IReadOnlyList<TokenTexto> tokens, int indice, IReadOnlyList<string> secuencia) =>
        secuencia.Select((valor, desplazamiento) => tokens[indice + desplazamiento].Valor == valor).All(coincide => coincide);

    private static void ProcesarRune(AcumuladorTokens acumulador, Rune rune, int inicio, int fin)
    {
        var plegado = PlegadoCompatibilidad.De(rune);
        if (plegado.Length == 0)
        {
            acumulador.Extender(fin);
            return;
        }

        foreach (var caracter in plegado)
        {
            Procesar(acumulador, char.ToLowerInvariant(caracter), inicio, fin);
        }
    }

    private static void Procesar(AcumuladorTokens acumulador, char minuscula, int inicio, int fin)
    {
        if (char.IsLetterOrDigit(minuscula))
        {
            acumulador.Agregar(minuscula, inicio, fin);
            return;
        }

        acumulador.Cerrar();
    }

    private sealed class AcumuladorTokens
    {
        private readonly List<TokenTexto> _tokens = [];
        private readonly StringBuilder _valor = new();
        private int _inicio;
        private int _fin;

        public IReadOnlyList<TokenTexto> Tokens => _tokens;

        public void Agregar(char caracter, int inicio, int fin)
        {
            if (_valor.Length == 0)
            {
                _inicio = inicio;
            }

            _valor.Append(caracter);
            _fin = fin;
        }

        public void Extender(int fin)
        {
            if (_valor.Length > 0)
            {
                _fin = fin;
            }
        }

        public void Cerrar()
        {
            if (_valor.Length == 0)
            {
                return;
            }

            _tokens.Add(new TokenTexto(_valor.ToString(), _inicio, _fin));
            _valor.Clear();
        }
    }

    [GeneratedRegex("<=|>=|[<>≤≥]", RegexOptions.CultureInvariant, matchTimeoutMilliseconds: TiempoLimiteRegex.Milisegundos)]
    private static partial Regex SimboloDeComparacion();
}

